const DECISION_MAKER_PATTERNS = [
  /\bceo\b/i,
  /\bfounder\b/i,
  /\bco[-\s]?founder\b/i,
  /\bowner\b/i,
  /\bdir(e|é)cteur(\s+g[eé]n[eé]ral)?\b/i,
  /\bmanaging director\b/i,
  /\bchief executive\b/i,
  /\bprésident\b/i,
  /\bgérant\b/i,
  /\bdirigean?t\b/i,
  /\bdg\b/i,
  /\bpdg\b/i,
  /\bassocié\b/i,
  /\bpartner\b/i,
  /\bhead of\b/i,
  /\bvp\b/i,
  /\bvice.?president\b/i,
  /\bcto\b/i,
  /\bcoo\b/i,
  /\bcmo\b/i
];

const MARKETING_PATTERNS = [
  /\bmarketing\b/i,
  /\bgrowth\b/i,
  /\bseo\b/i,
  /\btraffic\b/i,
  /\bcontent\b/i,
  /\bbrand\b/i
];

const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const headlineRaw = String(
    j.primaryTitle ||
    j.body?.headline ||
    ""
  );

  const headline = headlineRaw
    .toLowerCase()
    .replace(/[@|•\-–—]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  let role = "UNKNOWN";
  if (DECISION_MAKER_PATTERNS.some((r) => r.test(headline))) role = "DECISION_MAKER";
  else if (MARKETING_PATTERNS.some((r) => r.test(headline))) role = "MARKETING";

  out.push({
    json: {
      ...j,
      businessSignals: {
        role,
        detectedHeadline: headlineRaw,
        detectedAt: new Date().toISOString(),
        websiteStatus: j.websiteStatus || "UNKNOWN",
        websiteValid: j.websiteValid !== false,
        websiteNormalized: j.websiteNormalized || null
      }
    }
  });
}

return out;

const out = [];

for (const item of $input.all()) {
  const input      = item.json || {};
  const homepage   = input.seoHomepage    || {};
  const robotsRaw  = input.robots         || {};
  const sitemapRaw = input.sitemap        || {};
  const techFP     = input.techFingerprint || {};

  // ── FIX: HTTPS detection is done HERE (post-Merge)
  // because websiteNormalized is available after Merge but NOT in SEO Source Detector
  // (HTTP Request node replaces the input item with the response)
  const websiteNorm = String(input.websiteNormalized || "");
  const websiteRaw  = String(input.websiteRaw || "");

  // True HTTPS = normalized URL starts with https AND the raw original also was https
  // If raw was http:// → the normalizer forced https, but the server MAY still be HTTP
  // We use the security header (HSTS) as a confirmation signal
  const security = homepage.security || {};
  const normalizedIsHttps = websiteNorm.startsWith("https://");
  const rawWasHttp        = websiteRaw.startsWith("http://") && !websiteRaw.startsWith("https://");
  const serverConfirmsHttps = security.hasHSTS; // HSTS header = definitely HTTPS server

  // isHttps logic:
  // - If normalizedURL is https AND raw was already https → TRUE (original https)
  // - If normalizedURL is https AND raw was http → check HSTS to confirm server serves HTTPS
  // - If no https at all → FALSE
  let isHttps = false;
  if (normalizedIsHttps && !rawWasHttp) {
    isHttps = true;  // original URL was HTTPS → confirmed
  } else if (normalizedIsHttps && rawWasHttp) {
    // Normalizer upgraded http→https — confirm with HSTS header
    isHttps = serverConfirmsHttps;
  }

  // Patch security.isHttps in seoHomepage (override what SEO Source Detector set)
  const patchedSecurity = { ...security, isHttps };
  const patchedHomepage = { ...homepage, security: patchedSecurity };

  // ── Robots ──────────────────────────────────────────────────────
  const robotsBody =
    typeof robotsRaw.body === "string" ? robotsRaw.body :
    typeof robotsRaw.data === "string" ? robotsRaw.data : "";

  const robotsPresent =
    robotsRaw.present === true ||
    (typeof robotsRaw.statusCode === "number" &&
      robotsRaw.statusCode >= 200 && robotsRaw.statusCode < 400);

  const disallowRules    = (robotsBody.match(/^Disallow:/gim) || []).length;
  const disallowAll      = /disallow:\s*\/\s*$/im.test(robotsBody);
  const sitemapDirectives = [];
  for (const m of robotsBody.matchAll(/^Sitemap:\s*(.+)$/gim)) {
    const url = String(m[1] || "").trim();
    if (url) sitemapDirectives.push(url);
  }

  const robots = {
    present:             robotsPresent,
    disallowAll,
    disallowRules,
    hasSitemapDirective: sitemapDirectives.length > 0,
    sitemapDirectives,
  };

  // ── Sitemap ──────────────────────────────────────────────────────
  const sitemapBody =
    typeof sitemapRaw.body === "string" ? sitemapRaw.body :
    typeof sitemapRaw.data === "string" ? sitemapRaw.data : "";

  const sitemapPresent =
    sitemapRaw.present === true ||
    (typeof sitemapRaw.statusCode === "number" &&
      sitemapRaw.statusCode >= 200 && sitemapRaw.statusCode < 400);

  const sitemap = {
    present:         sitemapPresent,
    urlCount:        Number(sitemapRaw.urlCount || 0) || (sitemapBody.match(/<url>/gi) || []).length,
    hasImageSitemap: sitemapBody.includes("<image:image>"),
    hasNewsSitemap:  sitemapBody.includes("<news:news>"),
    hasSitemapIndex: sitemapBody.includes("<sitemapindex"),
  };

  // ── SEO normalized payload ───────────────────────────────────────
  const seo = {
    source:           "HTML",
    confidence:       techFP.auditCoverage !== "FULL" ? "PARTIAL" : "HIGH",
    confidenceFactor: techFP.auditCoverage !== "FULL" ? 0.7 : 1,
    homepage:         patchedHomepage,
    robots,
    sitemap,
    techFingerprint:  techFP,
  };

  out.push({ json: { ...input, seo } });
}

return out;

const out = [];

for (const item of $input.all()) {
  const body = item.json.body ?? {};
  const profileUrl = String(body.profileUrl || "").trim();
  const website = String(body.website || "").trim();

  const hasProfileUrl = profileUrl.length > 0;
  const hasWebsite = website.length > 0;

  out.push({
    json: {
      ...item.json,
      isValid: hasProfileUrl,
      validationStatus: hasProfileUrl ? "OK" : "INVALID",
      validationDetails: {
        hasProfileUrl,
        hasWebsite
      },
      validatedAt: new Date().toISOString()
    }
  });
}

return out;

const BLOCKED_HOSTS = [
  "linkedin.com",
  "facebook.com",
  "instagram.com",
  "x.com",
  "twitter.com",
  "youtube.com",
  "tiktok.com",
  "bing.com",
  "google.com"
];

function hostMatchesBlocked(host, token) {
  const h = String(host || "").toLowerCase();
  const t = String(token || "").toLowerCase();
  if (!h || !t) return false;
  return h === t || h.endsWith(`.${t}`);
}

function extractHost(rawInput) {
  let s = String(rawInput || "").trim();

  s = s
    .replace(/^["'`\s]+|["'`\s]+$/g, "")
    .replace(/[\u0000-\u001F\u007F-\u009F\u200B-\u200F\u202A-\u202E]/g, "");

  if (!s) return { ok: false, error: "NO_WEBSITE_FOUND" };

  if (!/^https?:\/\//i.test(s)) s = `https://${s}`;
  s = s.replace(/\\/g, "/");

  const m = s.match(/^https?:\/\/([^\/:?#\s]+)(?::\d+)?(?:[\/?#]|$)/i);
  if (!m || !m[1]) return { ok: false, error: "HOST_EXTRACT_FAILED", debugRaw: s };

  const host = m[1].toLowerCase().replace(/\.+$/, "");
  if (!/^[a-z0-9-]+(\.[a-z0-9-]+)+$/i.test(host)) {
    return { ok: false, error: "INVALID_HOSTNAME", debugRaw: s, host };
  }

  if (BLOCKED_HOSTS.some((b) => hostMatchesBlocked(host, b))) {
    return { ok: false, error: "BLOCKED_HOST", debugRaw: s, host };
  }

  return { ok: true, host, normalized: `https://${host}`, raw: s };
}

const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const raw =
    j.website ??
    j.body?.website ??
    j.params?.website ??
    j.query?.website ??
    "";

  const parsed = extractHost(raw);

  if (!parsed.ok) {
    out.push({
      json: {
        ...j,
        websiteRaw: String(raw || "").trim(),
        websiteNormalized: null,
        websiteHost: parsed.host || null,
        websiteValid: false,
        websiteStatus: parsed.error === "NO_WEBSITE_FOUND" ? "NO_WEBSITE" : "INVALID_WEBSITE",
        normalizeError: parsed.error,
        normalizeDebugRaw: parsed.debugRaw || null,
        normalizedAt: new Date().toISOString()
      }
    });
    continue;
  }

  out.push({
    json: {
      ...j,
      websiteRaw: parsed.raw,
      websiteNormalized: parsed.normalized,
      websiteHost: parsed.host,
      websiteValid: true,
      websiteStatus: "WEBSITE_OK",
      normalizeError: null,
      normalizedAt: new Date().toISOString()
    }
  });
}

return out;

const out = [];

// ── Utilities ──────────────────────────────────────────────────────
function pickBody(j) {
  if (typeof j?.body === "string") return j.body;
  if (typeof j?.data === "string") return j.data;
  if (typeof j?.raw === "string") return j.raw;
  return "";
}
function firstMatch(re, txt) {
  const m = txt.match(re);
  return m && m[1] ? String(m[1]).trim() : "";
}
function estimateWordCount(raw) {
  return raw
    .replace(/<script[\s\S]*?<\/script>/gi, "")
    .replace(/<style[\s\S]*?<\/style>/gi, "")
    .replace(/<[^>]+>/g, " ")
    .replace(/&[a-z#0-9]+;/gi, " ")
    .replace(/\s+/g, " ")
    .trim()
    .split(" ")
    .filter(w => w.length > 2).length;
}
function extractJsonLdTypes(raw) {
  const types = [];
  const regex = /<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m;
  while ((m = regex.exec(raw)) !== null) {
    try {
      const obj = JSON.parse(m[1]);
      const items = Array.isArray(obj) ? obj : [obj];
      for (const item of items) {
        if (item["@type"]) {
          const t = Array.isArray(item["@type"]) ? item["@type"] : [item["@type"]];
          types.push(...t);
        }
      }
    } catch {}
  }
  return [...new Set(types)];
}

// ── Technology Fingerprint ─────────────────────────────────────────
function detectTechnologies(raw, headers) {
  const h = k => String(headers[k] || headers[k.toLowerCase()] || "");
  const poweredBy = h("x-powered-by").toLowerCase();
  const serverH   = h("server").toLowerCase();

  const tech = {
    frameworks:    [],
    cms:           null,
    ecommerce:     null,
    siteBuilder:   null,
    renderType:    "UNKNOWN",  // SSR | CSR | CSR_BUILDER | SERVER_RENDERED | STATIC
    auditCoverage: "FULL",     // FULL | PARTIAL_JS | PARTIAL_BUILDER
    analytics:     {},
    serverHints:   [],
  };

  // ── SSR JS frameworks ──────────────────────────────────────
  if (/\b__NEXT_DATA__\b/.test(raw) || raw.includes("/_next/") || poweredBy.includes("next.js")) {
    tech.frameworks.push("Next.js");
    tech.renderType = "SSR";
  }
  if (raw.includes("__NUXT__") || raw.includes("/_nuxt/") || raw.includes("__NUXT_DATA__")) {
    tech.frameworks.push("Nuxt.js");
    tech.renderType = "SSR";
  }
  if (raw.includes("___gatsby") || raw.includes("/gatsby-chunk-")) {
    tech.frameworks.push("Gatsby");
    tech.renderType = "SSR";
  }
  if (raw.includes("astro-island") || /astro\.build\/client/i.test(raw)) {
    tech.frameworks.push("Astro");
    tech.renderType = "SSR";
  }
  if (/sveltekit|__sveltekit/i.test(raw)) {
    tech.frameworks.push("SvelteKit");
    tech.renderType = "SSR";
  }
  if (/remix\.run|__remixContext/i.test(raw)) {
    tech.frameworks.push("Remix");
    tech.renderType = "SSR";
  }

  // ── CSR JS frameworks (only if not already SSR) ─────────────
  const isSSR = tech.renderType === "SSR";
  if (!isSSR) {
    if (/data-reactroot|react\.production\.min|react\.development\.js/.test(raw)) {
      tech.frameworks.push("React (CSR)");
      if (tech.renderType === "UNKNOWN") tech.renderType = "CSR";
    }
    if (/__vue_app__|vue\.global\.prod|vue\.esm-bundler/.test(raw)) {
      tech.frameworks.push("Vue.js (CSR)");
      if (tech.renderType === "UNKNOWN") tech.renderType = "CSR";
    }
    if (/ng-version=|angular(?:\.min|\.core)\.js/i.test(raw)) {
      tech.frameworks.push("Angular (CSR)");
      if (tech.renderType === "UNKNOWN") tech.renderType = "CSR";
    }
    if (/ember\.(min\.)?js|Ember\.Application/i.test(raw)) {
      tech.frameworks.push("Ember.js (CSR)");
      if (tech.renderType === "UNKNOWN") tech.renderType = "CSR";
    }
  }

  // ── CMS ────────────────────────────────────────────────────
  if (raw.includes("/wp-content/") || raw.includes("/wp-includes/") || raw.includes("wp-json")) {
    tech.cms = "WordPress";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/\/components\/com_|joomla!/i.test(raw)) {
    tech.cms = "Joomla";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/drupal\.settings|drupal\.js|data-drupal/i.test(raw)) {
    tech.cms = "Drupal";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/typo3conf|typo3temp/i.test(raw)) {
    tech.cms = "TYPO3";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/shopware/i.test(raw)) {
    tech.cms = "Shopware";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/spip\//i.test(raw)) {
    tech.cms = "SPIP";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  }

  // ── E-commerce platforms ────────────────────────────────────
  if (raw.includes("cdn.shopify.com") || /Shopify\.(theme|shop|currency|PaymentButton)/i.test(raw) || /\.myshopify\.com/.test(raw)) {
    tech.ecommerce = "Shopify";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/woocommerce|wc-block-|wc-cart/i.test(raw)) {
    tech.ecommerce = "WooCommerce";
    if (!tech.cms) tech.cms = "WordPress";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/prestashop|presta-shop/i.test(raw)) {
    tech.ecommerce = "PrestaShop";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/\/mage\/|magento|mage-init|Mage\.Cookies/i.test(raw)) {
    tech.ecommerce = "Magento";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/opencart/i.test(raw)) {
    tech.ecommerce = "OpenCart";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/bigcommerce/i.test(raw)) {
    tech.ecommerce = "BigCommerce";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/wix\.stores|wixstores/i.test(raw)) {
    tech.ecommerce = "Wix Stores";
  }

  // ── Site Builders / No-code / AI builders ───────────────────
  if (raw.includes("static.wixstatic.com") || /wixsite\.com|wixpress\.com/i.test(raw)) {
    tech.siteBuilder = "Wix";
    tech.renderType  = "CSR_BUILDER";
  } else if (/squarespace\.com\/assets|\.squarespace\.com|sqsp\.net/i.test(raw)) {
    tech.siteBuilder = "Squarespace";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/webflow\.com\/css|\.webflow\.com|assets\.website-files\.com/i.test(raw)) {
    tech.siteBuilder = "Webflow";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/framer\.com\/m\/|framerusercontent\.com/i.test(raw)) {
    tech.siteBuilder = "Framer";
    tech.renderType  = "CSR_BUILDER";
  } else if (/bubble\.io/i.test(raw)) {
    tech.siteBuilder = "Bubble";
    tech.renderType  = "CSR_BUILDER";
  } else if (/editor\.jimdo\.com|\.jimdosite\.com/i.test(raw)) {
    tech.siteBuilder = "Jimdo";
    tech.renderType  = "CSR_BUILDER";
  } else if (/strikingly\.com/i.test(raw)) {
    tech.siteBuilder = "Strikingly";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/cargo\.site|2\.cargocollective\.com/i.test(raw)) {
    tech.siteBuilder = "Cargo";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/notion-static\.com|super\.so/i.test(raw)) {
    tech.siteBuilder = "Notion/Super";
    tech.renderType  = "CSR_BUILDER";
  } else if (/dorik\.com/i.test(raw)) {
    tech.siteBuilder = "Dorik";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/godaddy\.com\/gdcorp|godaddy-studio/i.test(raw)) {
    tech.siteBuilder = "GoDaddy";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  } else if (/shoptet\.cz|shoptet\.com/i.test(raw)) {
    tech.siteBuilder = "Shoptet";
    if (tech.renderType === "UNKNOWN") tech.renderType = "SERVER_RENDERED";
  }

  // ── Server tech hints ────────────────────────────────────────
  if (poweredBy.includes("php"))     tech.serverHints.push("PHP");
  if (poweredBy.includes("express")) tech.serverHints.push("Node/Express");
  if (poweredBy.includes("asp.net")) tech.serverHints.push("ASP.NET");
  if (poweredBy.includes("ruby"))    tech.serverHints.push("Ruby");
  if (serverH.includes("nginx"))     tech.serverHints.push("Nginx");
  if (serverH.includes("apache"))    tech.serverHints.push("Apache");
  if (serverH.includes("cloudflare")) tech.serverHints.push("Cloudflare");

  // ── Analytics signals (marketing intelligence) ───────────────
  tech.analytics = {
    hasGTM:     /googletagmanager\.com\/gtm/i.test(raw),
    hasGA4:     /gtag\('config'|google-analytics\.com\/g\//i.test(raw),
    hasGA3:     /ga\('create'|analytics\.js|ga\.js/i.test(raw),
    hasFBPixel: /connect\.facebook\.net.*fbevents/i.test(raw),
    hasHotjar:  /hotjar\.com/i.test(raw),
    hasIntercom:/intercom\.io|intercomcdn\.com/i.test(raw),
    hasMixpanel:/mixpanel\.com/i.test(raw),
    hasHubspot: /js\.hs-scripts\.com|hubspot\.com/i.test(raw),
    hasCrisp:   /crisp\.chat/i.test(raw),
    hasTidio:   /tidiochat\.com/i.test(raw),
  };

  // ── Audit coverage determination ─────────────────────────────
  if (tech.renderType === "CSR_BUILDER") {
    tech.auditCoverage = "PARTIAL_BUILDER";
  } else if (tech.renderType === "CSR") {
    tech.auditCoverage = "PARTIAL_JS";
  } else {
    tech.auditCoverage = "FULL";
  }

  if (tech.renderType === "UNKNOWN") tech.renderType = "STATIC";

  return tech;
}

// ── Main loop ──────────────────────────────────────────────────────
for (const item of $input.all()) {
  const j = item.json || {};
  const raw = pickBody(j);
  const headers = j.headers || {};
  const contentType = String(
    headers["content-type"] || headers["Content-Type"] || ""
  ).toLowerCase();
  const statusCode  = Number(j.statusCode || j.status || 0);
  const host        = String(j.websiteHost || "").toLowerCase();
  const websiteNorm = String(j.websiteNormalized || "");

  const homepage = {
    reachable:    statusCode >= 200 && statusCode < 400,
    statusCode:   statusCode || null,
    htmlLength:   0,
    // On-page
    hasTitle: false, title: "", titleLength: 0,
    hasMetaDescription: false, metaDescription: "", metaDescriptionLength: 0,
    hasH1: false, h1Count: 0, h2Count: 0, h3Count: 0,
    estimatedWordCount: 0,
    // Indexability
    hasCanonical: false, canonical: "",
    hasNoindex: false, hasNofollow: false,
    // Technical
    hasViewport: false,
    scriptCount: 0, headScriptCount: 0,
    isJsHeavy: false,
    isXml: false,
    hasLazyLoading: false, hasWebAppManifest: false,
    hasAmpLink: false, hasFavicon: false,
    hasCSSinline: false,
    // Structured data
    hasStructuredData: false, structuredDataTypes: [],
    hasMicrodata: false,
    // Social / OG
    hasOgTitle: false, ogTitle: "",
    hasOgDescription: false, ogDescription: "",
    hasOgImage: false, ogImageUrl: "",
    hasTwitterCard: false, twitterCardType: "",
    hasHreflang: false,
    // Images & Links
    imageCount: 0, imageMissingAltCount: 0,
    internalLinkCount: 0, externalLinkCount: 0,
    // Security (from headers)
    security: {
      isHttps:              null,  // resolved post-Merge in Normalize SEO Payload
      hasHSTS:              false,
      hasXFrameOptions:     false,
      hasCSP:               false,
      hasXContentTypeOptions: false,
      hasReferrerPolicy:    false,
    },
    reason: null
  };

  // Security headers
  const gh = name => Boolean(headers[name] || headers[name.toLowerCase()]);
  homepage.security.hasHSTS               = gh("strict-transport-security");
  homepage.security.hasXFrameOptions      = gh("x-frame-options");
  homepage.security.hasCSP                = gh("content-security-policy");
  homepage.security.hasXContentTypeOptions = gh("x-content-type-options");
  homepage.security.hasReferrerPolicy     = gh("referrer-policy");

  // XML / sitemap
  if (
    contentType.includes("xml") ||
    raw.startsWith("<?xml") ||
    raw.includes("<sitemapindex")
  ) {
    homepage.isXml = true;
    homepage.reason = "XML_RESPONSE";
    const techFingerprint = detectTechnologies(raw, headers);
    out.push({ json: { ...j, seoHomepage: homepage, techFingerprint } });
    continue;
  }

  const looksHtml =
    contentType.includes("text/html") ||
    /<!doctype html/i.test(raw) ||
    /<html[\s>]/i.test(raw);

  if (looksHtml) {
    homepage.htmlLength = raw.length;

    // ── Title ──
    const titleText = firstMatch(/<title[^>]*>([\s\S]*?)<\/title>/i, raw)
      .replace(/\s+/g, " ").trim();
    homepage.title        = titleText;
    homepage.hasTitle     = Boolean(titleText);
    homepage.titleLength  = titleText.length;

    // ── Meta Description ──
    const metaDesc =
      firstMatch(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i, raw) ||
      firstMatch(/<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description["']/i, raw);
    homepage.hasMetaDescription      = Boolean(metaDesc);
    homepage.metaDescription         = String(metaDesc || "").trim();
    homepage.metaDescriptionLength   = homepage.metaDescription.length;

    // ── Headings ──
    homepage.h1Count  = (raw.match(/<h1[^>]*>/gi) || []).length;
    homepage.h2Count  = (raw.match(/<h2[^>]*>/gi) || []).length;
    homepage.h3Count  = (raw.match(/<h3[^>]*>/gi) || []).length;
    homepage.hasH1    = homepage.h1Count > 0;

    // ── Viewport ──
    homepage.hasViewport = /(<meta[^>]+name=["']viewport["'])/i.test(raw);

    // ── Scripts ──
    homepage.scriptCount = (raw.match(/<script/gi) || []).length;
    const headMatch = raw.match(/<head[^>]*>([\s\S]*?)<\/head>/i);
    if (headMatch) {
      const headHtml = headMatch[1];
      homepage.headScriptCount = (
        headHtml.match(/<script(?![^>]*type=["'](?:application\/ld\+json|module)["'])[^>]*src=/gi) || []
      ).length;
    }

    // ── Inline CSS size ──
    const styleBlocks = raw.match(/<style[^>]*>([\s\S]*?)<\/style>/gi) || [];
    const inlineCssLen = styleBlocks.reduce((acc, s) => acc + s.length, 0);
    homepage.hasCSSinline = inlineCssLen > 2000;

    // ── Canonical ──
    const canonical =
      firstMatch(/<link[^>]+rel=["']canonical["'][^>]+href=["']([^"']+)["']/i, raw) ||
      firstMatch(/<link[^>]+href=["']([^"']+)["'][^>]+rel=["']canonical["']/i, raw);
    homepage.hasCanonical = Boolean(canonical);
    homepage.canonical    = canonical || "";

    // ── Robots meta ──
    const robotsMeta =
      firstMatch(/<meta[^>]+name=["']robots["'][^>]+content=["']([^"']*)["']/i, raw) ||
      firstMatch(/<meta[^>]+content=["']([^"']*)["'][^>]+name=["']robots["']/i, raw);
    const robotsNorm       = String(robotsMeta || "").toLowerCase();
    homepage.hasNoindex    = robotsNorm.includes("noindex");
    homepage.hasNofollow   = robotsNorm.includes("nofollow");

    // ── Open Graph ──
    homepage.hasOgTitle       = /(<meta[^>]+property=["']og:title["'])/i.test(raw);
    homepage.ogTitle          = firstMatch(/<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']*)["']/i, raw) || "";
    homepage.hasOgDescription = /(<meta[^>]+property=["']og:description["'])/i.test(raw);
    homepage.ogDescription    = firstMatch(/<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*)["']/i, raw) || "";
    homepage.hasOgImage       = /(<meta[^>]+property=["']og:image["'])/i.test(raw);
    homepage.ogImageUrl       = firstMatch(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']*)["']/i, raw) || "";
    homepage.hasTwitterCard   = /(<meta[^>]+name=["']twitter:card["'])/i.test(raw);
    homepage.twitterCardType  = firstMatch(/<meta[^>]+name=["']twitter:card["'][^>]+content=["']([^"']*)["']/i, raw) || "";
    homepage.hasHreflang      = /(<link[^>]+hreflang=)/i.test(raw);

    // ── Structured data ──
    homepage.hasStructuredData  = /(<script[^>]+type=["']application\/ld\+json["'])/i.test(raw);
    if (homepage.hasStructuredData) {
      homepage.structuredDataTypes = extractJsonLdTypes(raw);
    }
    homepage.hasMicrodata = /\bitemscope\b/i.test(raw);

    // ── Misc technical ──
    homepage.hasLazyLoading    = /loading=["']lazy["']/i.test(raw);
    homepage.hasAmpLink        = /(<link[^>]+rel=["']amphtml["'])/i.test(raw);
    homepage.hasFavicon        = /(<link[^>]+rel=["'](?:shortcut icon|icon)["'])/i.test(raw);
    homepage.hasWebAppManifest = /(<link[^>]+rel=["']manifest["'])/i.test(raw);

    // ── Images ──
    const imgTags = raw.match(/<img\b[^>]*>/gi) || [];
    homepage.imageCount          = imgTags.length;
    homepage.imageMissingAltCount = imgTags.filter(tag =>
      !/\balt\s*=\s*["'][^"']+["']/i.test(tag)
    ).length;

    // ── Links ──
    const hrefs = [...raw.matchAll(/<a\b[^>]*href\s*=\s*["']([^"']+)["']/gi)]
      .map(m => String(m[1] || ""));
    let internal = 0, external = 0;
    for (const href of hrefs) {
      if (!href || /^(#|javascript:|mailto:|tel:)/i.test(href)) continue;
      if (href.startsWith("/")) { internal++; continue; }
      if (/^https?:\/\//i.test(href)) {
        try {
          const h = new URL(href).hostname.toLowerCase();
          if (host && (h === host || h.endsWith(`.${host}`) || host.endsWith(`.${h}`))) internal++;
          else external++;
        } catch { external++; }
      }
    }
    homepage.internalLinkCount = internal;
    homepage.externalLinkCount = external;

    // ── Word count ──
    homepage.estimatedWordCount = estimateWordCount(raw);

    // ── Reason / JS Heavy ──
    if (statusCode === 401 || statusCode === 403 || statusCode === 429) {
      homepage.reason = `HTTP_${statusCode}_BLOCKED`;
    } else if (homepage.htmlLength < 25000 && homepage.scriptCount >= 14) {
      homepage.isJsHeavy = true;
      homepage.reason    = "JS_HEAVY_SITE";
    } else {
      homepage.reason = "HTML_OK";
    }

    const techFingerprint = detectTechnologies(raw, headers);
    out.push({ json: { ...j, seoHomepage: homepage, techFingerprint } });
    continue;
  }

  // Non-HTML fallback
  if (!homepage.reachable) {
    homepage.reason = statusCode >= 500 ? `HTTP_${statusCode}` : "NETWORK_OR_EMPTY";
  } else {
    homepage.reason = statusCode ? `HTTP_${statusCode}_NON_HTML` : "NON_HTML_RESPONSE";
  }

  const techFingerprint = detectTechnologies(raw, headers);
  out.push({ json: { ...j, seoHomepage: homepage, techFingerprint } });
}

return out;

const out = [];

// ─────────────────────────────────────────────────────────────────
// HELPERS
// ─────────────────────────────────────────────────────────────────

function issue(key, msg, severity = "warning") {
  return { key, msg, severity };
}
function pass(msg) {
  return msg;
}
function skip(key, msg) {
  return { key, msg, severity: "skip" };
}

// ─────────────────────────────────────────────────────────────────
// CATEGORY: INDEXABILITY (30 pts)  — always fully auditable
// ─────────────────────────────────────────────────────────────────
function scoreIndexability(homepage, robots, sitemap) {
  let score = 30;
  const issues = [], passed = [], skipped = [];

  if (homepage.hasNoindex) {
    score -= 30;
    issues.push(issue("noindex", "⛔ Meta robots: noindex détecté — page exclue des moteurs", "critical"));
  } else {
    passed.push("Pas de noindex");
  }

  if (robots.disallowAll) {
    score -= 20;
    issues.push(issue("robots_disallow_all", "⛔ robots.txt bloque tout le crawl (Disallow: /)", "critical"));
  } else if (!robots.present) {
    score -= 5;
    issues.push(issue("robots_missing", "robots.txt introuvable", "warning"));
  } else {
    passed.push(`robots.txt présent${robots.disallowRules > 0 ? ` — ${robots.disallowRules} règle(s) Disallow` : ""}`);
  }

  if (!homepage.hasCanonical) {
    score -= 6;
    issues.push(issue("canonical_missing", "Balise canonical absente", "warning"));
  } else if (!String(homepage.canonical || "").startsWith("https://")) {
    score -= 3;
    issues.push(issue("canonical_not_https", "Canonical ne pointe pas en HTTPS", "warning"));
  } else {
    passed.push("Canonical HTTPS défini");
  }

  if (!sitemap.present) {
    score -= 5;
    issues.push(issue("sitemap_missing", "sitemap.xml introuvable à /sitemap.xml", "warning"));
  } else if ((sitemap.urlCount || 0) === 0) {
    score -= 2;
    issues.push(issue("sitemap_empty", "Sitemap présent mais vide ou illisible", "warning"));
  } else {
    passed.push(`Sitemap XML présent — ${sitemap.urlCount} URL(s) détectée(s)`);
    if (sitemap.hasSitemapIndex) passed.push("Sitemap index multi-fichiers détecté");
  }

  if (robots.present && !robots.hasSitemapDirective) {
    score -= 1;
    issues.push(issue("robots_no_sitemap_ref", "robots.txt ne référence pas le sitemap", "info"));
  } else if (robots.hasSitemapDirective) {
    passed.push("Sitemap référencé dans robots.txt");
  }

  return { score: Math.max(0, Math.min(30, score)), max: 30, issues, passed, skipped };
}

// ─────────────────────────────────────────────────────────────────
// CATEGORY: ON-PAGE (35 pts) — adaptive for CSR / builders
// ─────────────────────────────────────────────────────────────────
function scoreOnPage(homepage, tech) {
  const isPartial   = tech.auditCoverage !== "FULL";
  const isEcommerce = Boolean(tech.ecommerce);
  const sdTypes     = homepage.structuredDataTypes || [];

  let score    = 35;
  let maxScore = 35;
  const issues = [], passed = [], skipped = [];

  // ── Title ──
  if (!homepage.hasTitle) {
    score -= 12; maxScore -= 0;
    issues.push(issue("title_missing", "⛔ Balise <title> absente", "critical"));
  } else if (homepage.titleLength < 30) {
    score -= 5;
    issues.push(issue("title_short", `Title trop court — ${homepage.titleLength} car. (min 30)`, "warning"));
  } else if (homepage.titleLength > 65) {
    score -= 2;
    issues.push(issue("title_long", `Title trop long — ${homepage.titleLength} car. (max 65)`, "info"));
  } else {
    passed.push(`Title OK — ${homepage.titleLength} car.`);
  }

  // ── Meta description ──
  if (!homepage.hasMetaDescription) {
    score -= 8; 
    issues.push(issue("desc_missing", "Meta description absente", "critical"));
  } else if (homepage.metaDescriptionLength < 70) {
    score -= 4;
    issues.push(issue("desc_short", `Meta description trop courte — ${homepage.metaDescriptionLength} car. (min 70)`, "warning"));
  } else if (homepage.metaDescriptionLength > 170) {
    score -= 2;
    issues.push(issue("desc_long", `Meta description trop longue — ${homepage.metaDescriptionLength} car. (max 170)`, "info"));
  } else {
    passed.push(`Meta description OK — ${homepage.metaDescriptionLength} car.`);
  }

  // ── H1 (skippable for CSR) ──
  if (isPartial && !homepage.hasH1) {
    maxScore -= 8;
    skipped.push(skip("h1_js", "H1 non analysable — contenu rendu côté client"));
  } else if (!homepage.hasH1) {
    score -= 8;
    issues.push(issue("h1_missing", "⛔ Balise H1 absente", "critical"));
  } else if (homepage.h1Count > 1) {
    // Ecommerce: multiple H1 more common, reduce penalty
    const penalty = isEcommerce ? 3 : 5;
    score -= penalty;
    issues.push(issue("h1_multiple", `${homepage.h1Count} H1 détectés (1 recommandé)`, "warning"));
  } else {
    passed.push("H1 unique présent");
  }

  // ── H2 structure (skippable for CSR) ──
  if (isPartial) {
    maxScore -= 2;
    skipped.push(skip("h2_js", "Structure H2/H3 non analysable — rendu client"));
  } else if ((homepage.h2Count || 0) === 0) {
    score -= 2;
    issues.push(issue("h2_missing", "Aucun H2 — structure de contenu plate", "info"));
  } else {
    passed.push(`${homepage.h2Count} H2${homepage.h3Count > 0 ? `, ${homepage.h3Count} H3` : ""} détectés`);
  }

  // ── Structured data ──
  if (!homepage.hasStructuredData && !homepage.hasMicrodata) {
    score -= 4;
    issues.push(issue("schema_missing", "Données structurées Schema.org absentes", "warning"));
  } else {
    const typeStr = sdTypes.length > 0 ? sdTypes.slice(0, 4).join(", ") : "microdata";
    passed.push(`Schema.org: ${typeStr}`);
    // Ecommerce bonus: check for Product/BreadcrumbList
    if (isEcommerce) {
      if (sdTypes.some(t => ["Product", "Offer", "ItemList"].includes(t))) {
        passed.push("Schema Product/Offer détecté — bon pour le rich snippet e-commerce");
      }
      if (sdTypes.includes("BreadcrumbList")) {
        passed.push("BreadcrumbList Schema détecté");
      }
    }
  }

  // ── Content depth (skippable for CSR) ──
  const wc = homepage.estimatedWordCount || 0;
  if (isPartial) {
    maxScore -= 4;
    skipped.push(skip("wordcount_js", "Volume de contenu non analysable — rendu client"));
  } else if (wc < 150) {
    score -= 4;
    issues.push(issue("thin_content", `Contenu très limité — ~${wc} mots estimés`, "warning"));
  } else if (wc < 400) {
    score -= 2;
    issues.push(issue("light_content", `Contenu estimé faible — ~${wc} mots`, "info"));
  } else {
    passed.push(`Contenu estimé: ~${wc} mots`);
  }

  // ── Builder SEO notice ──
  if (tech.siteBuilder) {
    const builderNotes = {
      "Wix":       "Wix: SEO basique disponible, mais dépend du plan et des paramètres",
      "Framer":    "Framer: SEO limité — title/meta définis manuellement par page",
      "Bubble":    "Bubble: SEO très limité — peu de contrôle natif",
      "Squarespace": "Squarespace: SEO correct nativement",
      "Webflow":   "Webflow: Bon contrôle SEO disponible",
    };
    const note = builderNotes[tech.siteBuilder];
    if (note) passed.push(note);
  }

  return {
    score:    Math.max(0, Math.min(maxScore, score)),
    max:      maxScore,
    issues, passed, skipped
  };
}

// ─────────────────────────────────────────────────────────────────
// CATEGORY: TECHNICAL (25 pts)
// ─────────────────────────────────────────────────────────────────
function scoreTechnical(homepage, tech) {
  let score = 25;
  const issues = [], passed = [], skipped = [];
  const security = homepage.security || {};

  // ── HTTPS ──
  if (!security.isHttps) {
    score -= 10;
    issues.push(issue("no_https", "⛔ Site non HTTPS — critique pour le référencement", "critical"));
  } else {
    passed.push("HTTPS actif");
  }

  // ── Mobile viewport ──
  if (!homepage.hasViewport) {
    score -= 5;
    issues.push(issue("no_viewport", "⛔ Meta viewport absent — site non mobile-friendly", "critical"));
  } else {
    passed.push("Viewport mobile présent");
  }

  // ── JS Heavy detection ──
  if (homepage.isJsHeavy || tech.renderType === "CSR" || tech.renderType === "CSR_BUILDER") {
    if (tech.renderType === "CSR_BUILDER") {
      score -= 3;
      issues.push(issue("csr_builder", `Site builder (${tech.siteBuilder || "no-code"}) — rendu client-side, crawlabilité partielle`, "warning"));
    } else if (homepage.isJsHeavy || tech.renderType === "CSR") {
      score -= 4;
      const fw = (tech.frameworks || []).join(", ") || "JS";
      issues.push(issue("js_heavy", `Rendu JS côté client (${fw}) — Googlebot peut avoir du mal à indexer le contenu`, "warning"));
    }
  } else {
    passed.push("Rendu côté serveur — crawlabilité optimale");
  }

  // ── Render-blocking scripts ──
  const hsc = homepage.headScriptCount || 0;
  if (hsc > 8) {
    score -= 4;
    issues.push(issue("render_blocking_high", `${hsc} scripts render-blocking dans <head> — impact LCP/FCP`, "warning"));
  } else if (hsc > 4) {
    score -= 2;
    issues.push(issue("render_blocking_moderate", `${hsc} scripts dans <head>`, "info"));
  } else if (hsc <= 2) {
    passed.push("Scripts <head> bien maîtrisés");
  }

  // ── HSTS ──
  if (security.isHttps) {
    if (!security.hasHSTS) {
      score -= 1;
      issues.push(issue("no_hsts", "HSTS non activé (Strict-Transport-Security)", "info"));
    } else {
      passed.push("HSTS activé");
    }
    if (security.hasXFrameOptions) passed.push("X-Frame-Options défini");
    if (security.hasCSP) passed.push("Content-Security-Policy présent");
    if (security.hasXContentTypeOptions) passed.push("X-Content-Type-Options défini");
  }

  // ── Favicon ──
  if (!homepage.hasFavicon) {
    score -= 1;
    issues.push(issue("no_favicon", "Favicon absent", "info"));
  } else {
    passed.push("Favicon présent");
  }

  // ── Tech stack bonuses ──
  if (homepage.hasWebAppManifest) passed.push("Web App Manifest (PWA) présent");
  if (homepage.hasAmpLink)        passed.push("Version AMP liée");
  if (homepage.hasLazyLoading)    passed.push("Lazy loading images activé");

  // ── Analytics presence (conversion intelligence) ──
  const a = tech.analytics || {};
  const analyticsTools = [];
  if (a.hasGTM)      analyticsTools.push("GTM");
  if (a.hasGA4)      analyticsTools.push("GA4");
  if (a.hasGA3)      analyticsTools.push("UA");
  if (a.hasFBPixel)  analyticsTools.push("FB Pixel");
  if (a.hasHotjar)   analyticsTools.push("Hotjar");
  if (a.hasHubspot)  analyticsTools.push("HubSpot");
  if (analyticsTools.length > 0) {
    passed.push(`Analytics: ${analyticsTools.join(", ")}`);
  } else {
    issues.push(issue("no_analytics", "Aucun outil d'analytics détecté", "info"));
  }

  // ── CMS / Platform identification ──
  if (tech.cms)         passed.push(`CMS: ${tech.cms}`);
  if (tech.ecommerce)   passed.push(`E-commerce: ${tech.ecommerce}`);
  if (tech.frameworks?.length > 0) {
    passed.push(`Framework: ${tech.frameworks.join(", ")}`);
  }

  return { score: Math.max(0, Math.min(25, score)), max: 25, issues, passed, skipped };
}

// ─────────────────────────────────────────────────────────────────
// CATEGORY: SOCIAL & MEDIA (10 pts)
// ─────────────────────────────────────────────────────────────────
function scoreSocial(homepage) {
  let score = 10;
  const issues = [], passed = [], skipped = [];

  if (!homepage.hasOgTitle) {
    score -= 2;
    issues.push(issue("og_title_missing", "og:title absent", "warning"));
  } else {
    passed.push(`og:title: "${String(homepage.ogTitle || "").slice(0, 40)}"`);
  }

  if (!homepage.hasOgDescription) {
    score -= 1;
    issues.push(issue("og_desc_missing", "og:description absent", "info"));
  }

  if (!homepage.hasOgImage) {
    score -= 2;
    issues.push(issue("og_image_missing", "og:image absent — partage social dégradé", "warning"));
  } else {
    passed.push("og:image présent");
  }

  if (!homepage.hasTwitterCard) {
    score -= 1;
    issues.push(issue("no_twitter_card", "Twitter Card absent", "info"));
  } else {
    passed.push(`Twitter Card: ${homepage.twitterCardType || "présent"}`);
  }

  // Images alt
  const imgCount    = homepage.imageCount || 0;
  const missingAlt  = homepage.imageMissingAltCount || 0;
  if (imgCount > 0) {
    const ratio = missingAlt / imgCount;
    if (ratio > 0.5) {
      score -= 3;
      issues.push(issue("alt_missing_many", `${missingAlt}/${imgCount} images sans attribut alt`, "warning"));
    } else if (missingAlt > 0) {
      score -= 1;
      issues.push(issue("alt_missing_some", `${missingAlt}/${imgCount} images sans alt`, "info"));
    } else {
      passed.push(`Alt text complet — ${imgCount} images`);
    }
  }

  if (homepage.hasHreflang) passed.push("Hreflang: internationalisation active");

  return { score: Math.max(0, Math.min(10, score)), max: 10, issues, passed, skipped };
}

// ─────────────────────────────────────────────────────────────────
// CLASSIFY UNREACHABLE
// ─────────────────────────────────────────────────────────────────
function classifyUnreachable(statusCode, reason) {
  const rs = String(reason || "").toUpperCase();
  const sc = Number(statusCode || 0);
  if (rs.includes("TIMEOUT")) return "SITE_TIMEOUT";
  if (rs.includes("DNS"))     return "SITE_DNS_ERROR";
  if (rs.includes("SSL") || rs.includes("TLS")) return "SITE_SSL_ERROR";
  if (sc === 401 || sc === 403) return "SITE_FORBIDDEN";
  if (sc === 404) return "SITE_NOT_FOUND";
  if (sc >= 500 && sc <= 599) return "SITE_SERVER_ERROR";
  return "SITE_UNREACHABLE";
}

// ─────────────────────────────────────────────────────────────────
// MAIN LOOP
// ─────────────────────────────────────────────────────────────────
for (const item of $input.all()) {
  const j        = item.json || {};
  const seo      = j.seo    || {};
  const homepage = seo.homepage || {};
  const robots   = seo.robots   || {};
  const sitemap  = seo.sitemap  || {};
  const tech     = seo.techFingerprint || {};

  const websiteStatus = String(j.websiteStatus || "UNKNOWN").toUpperCase();
  const websiteValid  = typeof j.websiteValid === "boolean" ? j.websiteValid : null;

  // ── No website ──────────────────────────────────────────────────
  if (websiteStatus === "NO_WEBSITE" || websiteStatus === "INVALID_WEBSITE" || websiteValid === false) {
    out.push({ json: {
      ...j,
      seoOpportunity: {
        rawScore: null, level: "NO_WEBSITE", siteType: "UNKNOWN",
        confidence: "HIGH", source: "INPUT", auditCoverage: "NONE",
        categories: null,
        issues: [issue(j.normalizeError || "no_website", j.normalizeError || "Aucun site web valide", "critical")],
        passed: [], skipped: [],
        technical: { websiteStatus, statusCode: homepage.statusCode || null },
        techFingerprint: tech,
        evaluatedAt: new Date().toISOString()
      }
    }});
    continue;
  }

  // ── Unreachable ─────────────────────────────────────────────────
  const reachable = homepage.reachable === true;
  if (!reachable) {
    const reason = String(homepage.reason || "");
    const level  = classifyUnreachable(homepage.statusCode, reason);
    out.push({ json: {
      ...j,
      seoOpportunity: {
        rawScore: null, level, siteType: "UNKNOWN",
        confidence: "HIGH", source: seo.source || "HTTP", auditCoverage: "NONE",
        categories: null,
        issues: [issue("unreachable", reason || "Homepage injoignable", "critical")],
        passed: [], skipped: [],
        technical: { websiteStatus, statusCode: homepage.statusCode || null },
        techFingerprint: tech,
        evaluatedAt: new Date().toISOString()
      }
    }});
    continue;
  }

  // ── Site type ───────────────────────────────────────────────────
  let siteType = "CONTENT";
  if (tech.ecommerce)                                                    siteType = "ECOMMERCE";
  else if (tech.cms)                                                     siteType = "CMS";
  else if (tech.siteBuilder)                                             siteType = "BUILDER";
  else if (tech.renderType === "CSR" || tech.renderType === "CSR_BUILDER") siteType = "SPA_APP";
  else if (tech.renderType === "SSR" && tech.frameworks?.length > 0)    siteType = "MODERN_SSR";
  else if ((homepage.htmlLength || 0) > 700000 && (homepage.scriptCount || 0) >= 10) siteType = "ENTERPRISE";
  else if ((homepage.htmlLength || 0) < 15000 && (homepage.estimatedWordCount || 0) < 200) siteType = "PERSONAL";
  else if (homepage.isJsHeavy)                                           siteType = "JS_APP";

  // ── Category scoring (adaptive) ─────────────────────────────────
  const catI = scoreIndexability(homepage, robots, sitemap);
  const catO = scoreOnPage(homepage, tech);
  const catT = scoreTechnical(homepage, tech);
  const catS = scoreSocial(homepage);

  // ── Total score — normalize to 100 if partial audit ─────────────
  const totalMax = catI.max + catO.max + catT.max + catS.max; // may be < 100 for CSR
  const rawRaw   = catI.score + catO.score + catT.score + catS.score;
  // Normalize to 100 scale so the score stays comparable
  const rawScore = totalMax < 100
    ? Math.round((rawRaw / totalMax) * 100)
    : rawRaw;

  // ── Aggregate issues / passed / skipped ──────────────────────────
  const allIssues  = [...catI.issues,  ...catO.issues,  ...catT.issues,  ...catS.issues];
  const allPassed  = [...catI.passed,  ...catO.passed,  ...catT.passed,  ...catS.passed];
  const allSkipped = [...catI.skipped, ...catO.skipped, ...catT.skipped, ...catS.skipped];

  // ── Level ────────────────────────────────────────────────────────
  const hasCritical = allIssues.some(i => i.severity === "critical");
  let level = "OK";
  if (homepage.hasNoindex || robots.disallowAll) level = "CRITICAL";
  else if (hasCritical || rawScore < 40)          level = "CRITICAL";
  else if (rawScore < 65)                          level = "WEAK";

  out.push({ json: {
    ...j,
    seoOpportunity: {
      rawScore,
      level,
      siteType,
      confidence:    seo.confidence || "MEDIUM",
      source:        seo.source     || "HTML",
      auditCoverage: tech.auditCoverage || "FULL",
      categories: {
        indexability: { score: catI.score, max: catI.max },
        onPage:       { score: catO.score, max: catO.max },
        technical:    { score: catT.score, max: catT.max },
        social:       { score: catS.score, max: catS.max },
        normalizedTo100: totalMax !== 100,
      },
      issues:  allIssues,
      passed:  allPassed,
      skipped: allSkipped,
      technical: {
        websiteStatus,
        statusCode:              homepage.statusCode || null,
        titleLength:             homepage.titleLength || 0,
        metaDescriptionLength:   homepage.metaDescriptionLength || 0,
        h1Count:                 homepage.h1Count || 0,
        h2Count:                 homepage.h2Count || 0,
        h3Count:                 homepage.h3Count || 0,
        estimatedWordCount:      homepage.estimatedWordCount || 0,
        scriptCount:             homepage.scriptCount || 0,
        headScriptCount:         homepage.headScriptCount || 0,
        htmlLength:              homepage.htmlLength || 0,
        hasCanonical:            homepage.hasCanonical === true,
        canonical:               homepage.canonical || "",
        hasNoindex:              homepage.hasNoindex === true,
        hasNofollow:             homepage.hasNofollow === true,
        hasViewport:             homepage.hasViewport === true,
        hasHreflang:             homepage.hasHreflang === true,
        hasOgTitle:              homepage.hasOgTitle === true,
        hasOgDescription:        homepage.hasOgDescription === true,
        hasOgImage:              homepage.hasOgImage === true,
        hasTwitterCard:          homepage.hasTwitterCard === true,
        imageCount:              homepage.imageCount || 0,
        imageMissingAltCount:    homepage.imageMissingAltCount || 0,
        internalLinkCount:       homepage.internalLinkCount || 0,
        externalLinkCount:       homepage.externalLinkCount || 0,
        hasStructuredData:       homepage.hasStructuredData === true,
        structuredDataTypes:     homepage.structuredDataTypes || [],
        hasFavicon:              homepage.hasFavicon === true,
        hasLazyLoading:          homepage.hasLazyLoading === true,
        isJsHeavy:               homepage.isJsHeavy === true,
        pageReason:              homepage.reason || null,
        security:                homepage.security || {},
        robotsPresent:           robots.present === true,
        robotsDisallowAll:       robots.disallowAll === true,
        robotsDisallowRules:     robots.disallowRules || 0,
        robotsHasSitemapRef:     robots.hasSitemapDirective === true,
        sitemapPresent:          sitemap.present === true,
        sitemapUrlCount:         sitemap.urlCount || 0,
        sitemapHasIndex:         sitemap.hasSitemapIndex === true,
      },
      techFingerprint: tech,
      evaluatedAt: new Date().toISOString()
    }
  }});
}

return out;

const ENABLE_HOT_FOR_CRITICAL_WITH_DM = true;

let seoOpp = null;
let businessSignals = {};
let websiteStatus = "UNKNOWN";

for (const item of items) {
  const j = item.json || {};
  if (j.seoOpportunity) seoOpp = j.seoOpportunity;
  if (j.businessSignals) {
    businessSignals = j.businessSignals;
    if (j.businessSignals.websiteStatus) websiteStatus = j.businessSignals.websiteStatus;
  }
  if (j.websiteStatus) websiteStatus = j.websiteStatus;
  if (j.seoOpportunity?.technical?.websiteStatus) websiteStatus = j.seoOpportunity.technical.websiteStatus;
}

const role             = businessSignals.role || "UNKNOWN";
const detectedHeadline = businessSignals.detectedHeadline || null;
const isDecisionMaker  = role === "DECISION_MAKER";

const seoLevelRaw      = seoOpp?.level || "UNKNOWN";
const effectiveSeoLevel =
  websiteStatus === "NO_WEBSITE" || websiteStatus === "INVALID_WEBSITE"
    ? "NO_WEBSITE"
    : seoLevelRaw;

let final = "IGNORE", leadType = "COLD_LEAD", confidence = "LOW", reason = "No actionable SEO signal";

if (!isDecisionMaker) {
  final = "FIND_DECISION_MAKER"; leadType = "WARM_LEAD"; confidence = "MEDIUM";
  reason = "Target role is not a decision-maker";
} else {
  if (effectiveSeoLevel === "NO_WEBSITE") {
    final = "CONTACT_SOFT"; leadType = "WARM_LEAD"; confidence = "HIGH";
    reason = "Decision-maker identified and company has no valid website";
  } else if ([
    "SITE_UNREACHABLE","SITE_TIMEOUT","SITE_DNS_ERROR",
    "SITE_SSL_ERROR","SITE_FORBIDDEN","SITE_NOT_FOUND","SITE_SERVER_ERROR"
  ].includes(effectiveSeoLevel)) {
    final = "CONTACT_SOFT"; leadType = "WARM_LEAD"; confidence = "HIGH";
    reason = "Decision-maker identified and website is unreachable";
  } else if (effectiveSeoLevel === "CRITICAL") {
    final      = ENABLE_HOT_FOR_CRITICAL_WITH_DM ? "CONTACT_NOW"  : "CONTACT_SOFT";
    leadType   = ENABLE_HOT_FOR_CRITICAL_WITH_DM ? "HOT_LEAD"     : "WARM_LEAD";
    confidence = "HIGH";
    reason     = "Decision-maker identified and SEO is critical";
  } else if (effectiveSeoLevel === "WEAK") {
    final = "CONTACT_SOFT"; leadType = "WARM_LEAD"; confidence = "MEDIUM";
    reason = "Decision-maker identified and SEO has weaknesses";
  } else if (effectiveSeoLevel === "OK") {
    final = "IGNORE"; leadType = "COLD_LEAD"; confidence = "MEDIUM";
    reason = "SEO baseline looks healthy";
  }
}

return [{
  json: {
    decision: {
      leadType, final, confidence, reason,
      signals: {
        seoLevel:       effectiveSeoLevel,
        siteType:       seoOpp?.siteType       || "UNKNOWN",
        auditCoverage:  seoOpp?.auditCoverage  || "FULL",
        role, websiteStatus,
        rawScore:       typeof seoOpp?.rawScore === "number" ? seoOpp.rawScore : null,
        seoSource:      seoOpp?.source         || null,
        seoIssues:      Array.isArray(seoOpp?.issues)  ? seoOpp.issues  : [],
        seoPassed:      Array.isArray(seoOpp?.passed)  ? seoOpp.passed  : [],
        seoSkipped:     Array.isArray(seoOpp?.skipped) ? seoOpp.skipped : [],
        categories:     seoOpp?.categories     || null,
        techFingerprint: seoOpp?.techFingerprint || {},
        cwv: seoOpp?.cwv || null,
      },
      engine: { name: "n8n_business_engine", version: "v11.0", decidedAt: new Date().toISOString() },
      detectedHeadline,
    }
  }
}];

const decision = $json.decision;
if (!decision) throw new Error("UI_MAPPER: decision missing");

const {
  final,
  confidence = "LOW",
  reason = "",
  detectedHeadline = "No headline detected",
  signals = {}
} = decision;

const seoLevel     = signals.seoLevel    || "UNKNOWN";
const role         = signals.role        || "UNKNOWN";
const rawScore     = typeof signals.rawScore === "number" ? signals.rawScore : null;
const categories   = signals.categories  || null;
const techFP       = signals.techFingerprint || {};
const auditCoverage = signals.auditCoverage || "FULL";
const siteType     = signals.siteType    || "UNKNOWN";

// ── SEO Badge ──────────────────────────────────────────────────────
const SEO_MAP = {
  NO_WEBSITE:        { badge: "NO WEBSITE",    color: "gray",   emoji: "—", label: "Aucun site web détecté" },
  SITE_TIMEOUT:      { badge: "TIMEOUT",       color: "orange", emoji: "⏱", label: "Site injoignable (timeout)" },
  SITE_DNS_ERROR:    { badge: "DNS ERROR",     color: "orange", emoji: "⚠", label: "Erreur DNS" },
  SITE_SSL_ERROR:    { badge: "SSL ERROR",     color: "orange", emoji: "🔒", label: "Erreur certificat SSL" },
  SITE_FORBIDDEN:    { badge: "BLOCKED 403",   color: "orange", emoji: "⛔", label: "Accès bloqué (403)" },
  SITE_NOT_FOUND:    { badge: "404 NOT FOUND", color: "orange", emoji: "?", label: "Site introuvable (404)" },
  SITE_SERVER_ERROR: { badge: "SERVER 5xx",    color: "orange", emoji: "💥", label: "Erreur serveur" },
  SITE_UNREACHABLE:  { badge: "UNREACHABLE",   color: "orange", emoji: "⚠", label: "Site injoignable" },
  CRITICAL:          { badge: "SEO CRITIQUE",  color: "red",    emoji: "✕", label: "Problèmes SEO critiques" },
  WEAK:              { badge: "SEO FAIBLE",    color: "orange", emoji: "!", label: "Faiblesses SEO détectées" },
  OK:                { badge: "SEO OK",        color: "green",  emoji: "✓", label: "Baseline SEO saine" },
};

const seoEntry = SEO_MAP[seoLevel] || { badge: "SEO UNKNOWN", color: "gray", emoji: "?", label: "Non évalué" };
const { badge: seoBadge, color: seoColor, emoji: seoEmoji, label: seoLabel } = seoEntry;

// ── Score display ──────────────────────────────────────────────────
const scoreDisplay = rawScore !== null ? `${rawScore}/100` : null;
let scoreColor = "gray";
if (rawScore !== null) {
  scoreColor = rawScore >= 75 ? "green" : rawScore >= 50 ? "orange" : "red";
}

// ── Categories ─────────────────────────────────────────────────────
let categoriesDisplay = null;
if (categories) {
  categoriesDisplay = {
    indexability: `${categories.indexability.score}/${categories.indexability.max}`,
    onPage:       `${categories.onPage.score}/${categories.onPage.max}`,
    technical:    `${categories.technical.score}/${categories.technical.max}`,
    social:       `${categories.social.score}/${categories.social.max}`,
  };
}

// ── Audit coverage label ───────────────────────────────────────────
const COVERAGE_MAP = {
  FULL:             { label: "Audit complet",              color: "green"  },
  PARTIAL_JS:       { label: "Audit partiel — SPA/CSR",   color: "orange" },
  PARTIAL_BUILDER:  { label: "Audit partiel — Site builder", color: "orange" },
  NONE:             { label: "Site inaccessible",          color: "gray"   },
};
const coverageEntry = COVERAGE_MAP[auditCoverage] || { label: auditCoverage, color: "gray" };

// ── Tech stack label ───────────────────────────────────────────────
const techParts = [];
if (techFP.ecommerce)              techParts.push(techFP.ecommerce);
if (techFP.cms)                    techParts.push(techFP.cms);
if (techFP.siteBuilder)            techParts.push(techFP.siteBuilder);
if (techFP.frameworks?.length > 0) techParts.push(...techFP.frameworks.slice(0, 2));
const techStackLabel = techParts.length > 0 ? techParts.join(" · ") : null;

// ── Site type label ────────────────────────────────────────────────
const SITE_TYPE_MAP = {
  ECOMMERCE:   "🛍 E-commerce",
  CMS:         "📝 CMS",
  BUILDER:     "🔧 Site Builder",
  SPA_APP:     "⚡ SPA/App",
  MODERN_SSR:  "🚀 SSR moderne",
  ENTERPRISE:  "🏢 Enterprise",
  PERSONAL:    "👤 Site personnel",
  JS_APP:      "⚡ JS Heavy",
  CONTENT:     "📄 Site vitrine",
  UNKNOWN:     "Site web",
};
const siteTypeLabel = SITE_TYPE_MAP[siteType] || "Site web";

// ── Analytics ─────────────────────────────────────────────────────
const a = techFP.analytics || {};
const analyticsActive = [];
if (a.hasGTM)    analyticsActive.push("GTM");
if (a.hasGA4)    analyticsActive.push("GA4");
if (a.hasFBPixel) analyticsActive.push("FB Pixel");
if (a.hasHotjar) analyticsActive.push("Hotjar");
if (a.hasHubspot) analyticsActive.push("HubSpot");

// ── Action mapping ──────────────────────────────────────────────────
const ACTION_MAP = {
  CONTACT_NOW:         { label: "Contacter maintenant", color: "red",    emoji: "🔥", priority: 1 },
  CONTACT_SOFT:        { label: "Contacter (soft)",     color: "orange", emoji: "📬", priority: 2 },
  FIND_DECISION_MAKER: { label: "Trouver le décideur",  color: "yellow", emoji: "🔍", priority: 3 },
  IGNORE:              { label: "Ignorer",               color: "gray",   emoji: "⏭", priority: 4 },
};
const actionMap   = ACTION_MAP[final] || ACTION_MAP.IGNORE;

// ── Issues summary ──────────────────────────────────────────────────
const issuesList     = Array.isArray(signals.seoIssues) ? signals.seoIssues : [];
const criticalCount  = issuesList.filter(i => typeof i === "object" && i.severity === "critical").length;
const warningCount   = issuesList.filter(i => typeof i === "object" && i.severity === "warning").length;

return {
  json: {
    ...$json,
    ui: {
      // SEO status
      seoBadge, seoColor, seoEmoji, seoLabel,
      // Score
      scoreDisplay, scoreColor, rawScore,
      categoriesDisplay,
      // Site intelligence
      siteType, siteTypeLabel,
      techStackLabel,
      renderType:   techFP.renderType   || null,
      auditCoverage,
      auditCoverageLabel: coverageEntry.label,
      auditCoverageColor: coverageEntry.color,
      // Analytics
      analyticsDetected: analyticsActive,
      hasAnalytics: analyticsActive.length > 0,
      // Action
      actionLabel: actionMap.label,
      actionColor: actionMap.color,
      actionEmoji: actionMap.emoji,
      // Lead info
      role: role === "DECISION_MAKER" ? "Décideur" : role === "MARKETING" ? "Marketing" : "Rôle inconnu",
      detectedHeadline,
      confidence, reason,
      // Issues summary
      criticalCount, warningCount,
      // CWV & Performance
      mobilePerf:   signals.cwv?.scores?.performance  ?? null,
      mobileA11y:   signals.cwv?.scores?.accessibility ?? null,
      psSeoScore:   signals.cwv?.scores?.seo           ?? null,
      lcpMs:        signals.cwv?.metrics?.lcp ?? null,
      clsScore:     signals.cwv?.metrics?.cls ?? null,
      fcpMs:        signals.cwv?.metrics?.fcp ?? null,
      tbtMs:        signals.cwv?.metrics?.tbt ?? null,
      cwvFieldLcp:  signals.cwv?.fieldData?.lcp ?? null,
      cwvFieldCls:  signals.cwv?.fieldData?.cls ?? null,
      cwvDelta:     signals.cwv?.delta ?? null,
    }
  }
};

// CWV Score Adjuster — applies PageSpeed / CWV corrections on top of rawScore
const out = [];
for (const item of $input.all()) {
  const j      = item.json || {};
  const seoOpp = j.seoOpportunity;
  const cwv    = j.cwvData;
  if (!seoOpp || typeof seoOpp.rawScore !== 'number' || !cwv) {
    out.push({ json: { ...j, cwvAdjusted: false } }); continue;
  }
  const base    = seoOpp.rawScore;
  const scores  = cwv.mobile?.scores  || {};
  const metrics = cwv.mobile?.cwv     || {};
  let delta = 0;
  const cwvIssues = [], cwvPassed = [];

  // Performance
  const perf = scores.performance;
  if (typeof perf === 'number') {
    if      (perf >= 90) { delta += 5; cwvPassed.push('Performance mobile: ' + perf + '/100 — excellente'); }
    else if (perf >= 70) { delta += 2; cwvPassed.push('Performance mobile: ' + perf + '/100 — bonne'); }
    else if (perf >= 50) { delta -= 4; cwvIssues.push({ key:'perf_avg',  msg:'Performance mobile: ' + perf + '/100 — lente',          severity:'warning'  }); }
    else                 { delta -= 9; cwvIssues.push({ key:'perf_poor', msg:'⛔ Performance mobile critique: ' + perf + '/100 — très lente', severity:'critical' }); }
  }

  // LCP
  const lcp = metrics.lcp;
  if (typeof lcp === 'number') {
    if      (lcp > 4000) { delta -= 4; cwvIssues.push({ key:'lcp_poor', msg:'LCP: ' + (lcp/1000).toFixed(1) + 's — très lent (cible <2.5s)',    severity:'critical' }); }
    else if (lcp > 2500) { delta -= 2; cwvIssues.push({ key:'lcp_avg',  msg:'LCP: ' + (lcp/1000).toFixed(1) + 's — à améliorer (cible <2.5s)', severity:'warning'  }); }
    else                 { cwvPassed.push('LCP OK: ' + (lcp/1000).toFixed(1) + 's'); }
  }

  // CLS
  const cls = metrics.cls;
  if (typeof cls === 'number') {
    if      (cls > 0.25) { delta -= 3; cwvIssues.push({ key:'cls_poor', msg:'CLS: ' + cls.toFixed(3) + ' — instable (cible <0.1)',      severity:'warning' }); }
    else if (cls > 0.1)  { delta -= 1; cwvIssues.push({ key:'cls_avg',  msg:'CLS: ' + cls.toFixed(3) + ' — à améliorer (cible <0.1)', severity:'info'    }); }
    else                 { cwvPassed.push('CLS OK: ' + cls.toFixed(3)); }
  }

  // Accessibility
  const a11y = scores.accessibility;
  if (typeof a11y === 'number') {
    if      (a11y >= 90) { delta += 2; cwvPassed.push('Accessibilité: ' + a11y + '/100'); }
    else if (a11y < 70)  { delta -= 2; cwvIssues.push({ key:'a11y_poor', msg:'Accessibilité: ' + a11y + '/100', severity:'warning' }); }
  }

  // PageSpeed SEO audit
  const psSeo = scores.seo;
  if (typeof psSeo === 'number') {
    if   (psSeo < 70) { delta -= 3; cwvIssues.push({ key:'ps_seo_poor', msg:'PageSpeed SEO: ' + psSeo + '/100', severity:'warning' }); }
    else              { cwvPassed.push('PageSpeed SEO: ' + psSeo + '/100'); }
  }

  // Inner pages (info only)
  if (cwv.innerPages?.blog?.reachable)     cwvPassed.push('/blog accessible — contenu SEO détecté');
  if (cwv.innerPages?.services?.reachable) cwvPassed.push('/services accessible — structure du site claire');

  // Carbon (info only)
  if (cwv.carbon) {
    cwvPassed.push(cwv.carbon.green
      ? 'Hébergement vert (éco-responsable)'
      : 'Hébergement non vert — impact carbone à considérer');
  }

  const adjusted = Math.max(0, Math.min(100, base + delta));
  const UNREACHABLE = ['NO_WEBSITE','SITE_UNREACHABLE','SITE_TIMEOUT','SITE_DNS_ERROR','SITE_SSL_ERROR','SITE_FORBIDDEN','SITE_NOT_FOUND','SITE_SERVER_ERROR'];
  let lvl = seoOpp.level;
  if (!UNREACHABLE.includes(lvl)) {
    const hasCrit = [...(seoOpp.issues || []), ...cwvIssues].some(i => i && i.severity === 'critical');
    if      (hasCrit || adjusted < 40) lvl = 'CRITICAL';
    else if (adjusted < 65)            lvl = 'WEAK';
    else                               lvl = 'OK';
  }

  out.push({ json: { ...j, cwvAdjusted: true, seoOpportunity: {
    ...seoOpp,
    rawScore: adjusted,
    level:    lvl,
    issues:   [...(seoOpp.issues  || []), ...cwvIssues],
    passed:   [...(seoOpp.passed  || []), ...cwvPassed],
    cwv: { delta, base, adjusted, scores, metrics, fieldData: cwv.mobile?.fieldData || null, carbon: cwv.carbon || null, gatheredAt: cwv.gatheredAt || null },
  } } });
}
return out;

// Extract CWV — reads PageSpeed response, produces cwvData
const j = $json;

function extractPS(data) {
  if (!data || !data.lighthouseResult) return null;
  const lhr  = data.lighthouseResult;
  const cats = lhr.categories || {};
  const aud  = lhr.audits    || {};
  const s = c => (c && typeof c.score === 'number') ? Math.round(c.score * 100) : null;
  const n = k => { const v = aud[k]?.numericValue; return typeof v === 'number' ? Math.round(v) : null; };
  return {
    scores: {
      performance:   s(cats.performance),
      seo:           s(cats.seo),
      accessibility: s(cats.accessibility),
      bestPractices: s(cats['best-practices']),
    },
    cwv: {
      lcp: n('largest-contentful-paint'),
      cls: typeof aud['cumulative-layout-shift']?.numericValue === 'number'
        ? Math.round(aud['cumulative-layout-shift'].numericValue * 1000) / 1000 : null,
      fcp: n('first-contentful-paint'),
      tbt: n('total-blocking-time'),
      si:  n('speed-index'),
    },
    fieldData: {
      lcp: data.loadingExperience?.metrics?.LARGEST_CONTENTFUL_PAINT_MS?.category  || null,
      cls: data.loadingExperience?.metrics?.CUMULATIVE_LAYOUT_SHIFT_SCORE?.category || null,
      fcp: data.loadingExperience?.metrics?.FIRST_CONTENTFUL_PAINT_MS?.category    || null,
    },
  };
}

return { json: {
  cwvData: {
    mobile: extractPS(j),
    gatheredAt: new Date().toISOString(),
  }
} };
